INSERT INTO quizzes (id, topic_id, title, title_hi, total_questions, time_limit_mins, is_premium, difficulty, is_previous_year, description, description_hi) VALUES (1294, 1158, 'National Parks & Tiger Reserves Master Quiz', 'राष्ट्रीय उद्यान एवं टाइगर रिजर्व मास्टर क्विज़', 20, 20, 0, 'medium', 0, 'Master Chhattisgarh''s protected areas with this CGPSC Prelims quiz. Evaluate your knowledge of the state''s 3 National Parks, 4 Tiger Reserves, establishment years, areas, and unique flora/fauna.', 'इस सीजीपीएससी प्रीलिम्स क्विज़ के साथ छत्तीसगढ़ के संरक्षित क्षेत्रों पर अपनी पकड़ मजबूत करें। राज्य के 3 राष्ट्रीय उद्यानों, 4 टाइगर रिजर्व, स्थापना वर्षों, क्षेत्रफल और अद्वितीय वनस्पतियों/जीवों के अपने ज्ञान का मूल्यांकन करें।');

INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Indravati National Park, the first national park of Chhattisgarh, was established in which of the following years?', 'छत्तीसगढ़ का प्रथम राष्ट्रीय उद्यान, इंद्रावती राष्ट्रीय उद्यान, निम्नलिखित में से किस वर्ष स्थापित किया गया था?', '1975', '1975', '1978', '1978', '1981', '1981', '1982', '1982', 2, 'Indravati National Park, located in the Bijapur district, was established in 1978. It is the first and oldest National Park of Chhattisgarh, covering an area of 1258 sq km.', 'बीजापुर जिले में स्थित इंद्रावती राष्ट्रीय उद्यान की स्थापना 1978 में हुई थी। यह 1258 वर्ग किलोमीटर क्षेत्र में फैला हुआ छत्तीसगढ़ का पहला और सबसे पुराना राष्ट्रीय उद्यान है।', 1);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Which of the following National Parks is the largest in Chhattisgarh in terms of geographical area?', 'भौगोलिक क्षेत्रफल की दृष्टि से छत्तीसगढ़ का सबसे बड़ा राष्ट्रीय उद्यान निम्नलिखित में से कौन सा है?', 'Indravati National Park', 'इंद्रावती राष्ट्रीय उद्यान', 'Kanger Valley National Park', 'कांगेर घाटी राष्ट्रीय उद्यान', 'Guru Ghasidas National Park', 'गुरु घासीदास राष्ट्रीय उद्यान', 'Sanjay Dubri National Park', 'संजय दुबरी राष्ट्रीय उद्यान', 3, 'Guru Ghasidas National Park, formerly a part of Sanjay National Park, is the largest in Chhattisgarh with an area of 1441 sq km. It spans across Koriya, MCB, and Surajpur districts.', 'गुरु घासीदास राष्ट्रीय उद्यान (पूर्व में संजय राष्ट्रीय उद्यान का हिस्सा) 1441 वर्ग किमी क्षेत्रफल के साथ छत्तीसगढ़ का सबसे बड़ा राष्ट्रीय उद्यान है। इसका विस्तार कोरिया, एमसीबी और सूरजपुर जिलों में है।', 2);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Consider the following statements regarding Kanger Valley National Park:

1. It was established in the year 1982.
2. It is the smallest national park in Chhattisgarh with an area of 200 sq km.
3. It currently holds the status of a Biosphere Reserve under the MAB program.

Which of the statement(s) given above is/are correct?', 'कांगेर घाटी राष्ट्रीय उद्यान के संबंध में निम्नलिखित कथनों पर विचार करें:

1. इसकी स्थापना वर्ष 1982 में हुई थी।
2. यह 200 वर्ग किमी क्षेत्रफल के साथ छत्तीसगढ़ का सबसे छोटा राष्ट्रीय उद्यान है।
3. यह वर्तमान में MAB कार्यक्रम के तहत बायोस्फीयर रिजर्व का दर्जा रखता है।

ऊपर दिए गए कथनों में से कौन सा/से सही है/हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 1, 'Statements 1 and 2 are correct. Statement 3 is incorrect because while it was declared Asia''s first biosphere reserve in 1982, it does not hold that status currently (Achanakmar is the only current Biosphere Reserve in CG).', 'कथन 1 और 2 सही हैं। कथन 3 गलत है क्योंकि यद्यपि इसे 1982 में एशिया का पहला बायोस्फीयर रिजर्व घोषित किया गया था, लेकिन वर्तमान में इसके पास यह दर्जा नहीं है (अचानकमार छ.ग. का एकमात्र वर्तमान बायोस्फीयर रिजर्व है)।', 3);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Match the following protected areas with their respective districts:

List-I
(a) Indravati National Park
(b) Guru Ghasidas National Park
(c) Kanger Valley National Park
(d) Achanakmar Tiger Reserve

List-II
(i) Mungeli
(ii) Bijapur
(iii) Bastar
(iv) Koriya/Surajpur

Codes:', 'निम्नलिखित संरक्षित क्षेत्रों को उनके संबंधित जिलों के साथ सुमेलित करें:

सूची-I
(a) इंद्रावती राष्ट्रीय उद्यान
(b) गुरु घासीदास राष्ट्रीय उद्यान
(c) कांगेर घाटी राष्ट्रीय उद्यान
(d) अचानकमार टाइगर रिजर्व

सूची-II
(i) मुंगेली
(ii) बीजापुर
(iii) बस्तर
(iv) कोरिया/सूरजपुर

कूट:', '(a)-(ii), (b)-(iv), (c)-(i), (d)-(iii)', '(a)-(ii), (b)-(iv), (c)-(i), (d)-(iii)', '(a)-(iv), (b)-(ii), (c)-(iii), (d)-(i)', '(a)-(iv), (b)-(ii), (c)-(iii), (d)-(i)', '(a)-(ii), (b)-(iv), (c)-(iii), (d)-(i)', '(a)-(ii), (b)-(iv), (c)-(iii), (d)-(i)', '(a)-(iii), (b)-(i), (c)-(iv), (d)-(ii)', '(a)-(iii), (b)-(i), (c)-(iv), (d)-(ii)', 3, 'Indravati is in Bijapur, Guru Ghasidas spans Koriya/Surajpur/MCB, Kanger Valley is in Bastar, and Achanakmar is in Mungeli.', 'इंद्रावती बीजापुर में है, गुरु घासीदास कोरिया/सूरजपुर/एमसीबी में फैला है, कांगेर घाटी बस्तर में है, और अचानकमार मुंगेली में है।', 4);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Assertion (A): Guru Ghasidas-Tamor Pingla has been recently notified as a new Tiger Reserve.

Reason (R): It has been officially declared as the 56th Tiger Reserve of India and the 4th Tiger Reserve of Chhattisgarh in 2024.

Codes:', 'कथन (A): गुरु घासीदास-तमोर पिंगला को हाल ही में एक नए टाइगर रिजर्व के रूप में अधिसूचित किया गया है।

कारण (R): इसे 2024 में आधिकारिक तौर पर भारत के 56वें और छत्तीसगढ़ के चौथे टाइगर रिजर्व के रूप में घोषित किया गया है।

कूट:', 'Both A and R are true, and R is the correct explanation of A.', 'A और R दोनों सत्य हैं, और R, A का सही स्पष्टीकरण है।', 'Both A and R are true, but R is not the correct explanation of A.', 'A और R दोनों सत्य हैं, लेकिन R, A का सही स्पष्टीकरण नहीं है।', 'A is true, but R is false.', 'A सत्य है, लेकिन R असत्य है।', 'A is false, but R is true.', 'A असत्य है, लेकिन R सत्य है।', 1, 'Both statements are absolutely correct. The combination of Guru Ghasidas NP and Tamor Pingla WLS was notified as India''s 56th and CG''s 4th Tiger Reserve in 2024.', 'दोनों कथन बिल्कुल सही हैं। गुरु घासीदास राष्ट्रीय उद्यान और तमोर पिंगला अभयारण्य के संयोजन को 2024 में भारत के 56वें और छत्तीसगढ़ के चौथे टाइगर रिजर्व के रूप में अधिसूचित किया गया था।', 5);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Arrange the National Parks of Chhattisgarh in chronological order of their establishment:

1. Kanger Valley National Park
2. Indravati National Park
3. Guru Ghasidas National Park

Choose the correct code:', 'छत्तीसगढ़ के राष्ट्रीय उद्यानों को उनकी स्थापना के कालानुक्रमिक (समय के) क्रम में व्यवस्थित करें:

1. कांगेर घाटी राष्ट्रीय उद्यान
2. इंद्रावती राष्ट्रीय उद्यान
3. गुरु घासीदास राष्ट्रीय उद्यान

सही कूट चुनें:', '2, 1, 3', '2, 1, 3', '3, 2, 1', '3, 2, 1', '1, 2, 3', '1, 2, 3', '2, 3, 1', '2, 3, 1', 4, 'The exact sequence is Indravati (1978) -> Guru Ghasidas (1981) -> Kanger Valley (1982). Examiners frequently test this specific chronology.', 'सटीक क्रम इंद्रावती (1978) -> गुरु घासीदास (1981) -> कांगेर घाटी (1982) है। परीक्षक अक्सर इस विशिष्ट कालक्रम का परीक्षण करते हैं।', 6);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'The Kutru Game Sanctuary, the only game sanctuary of Chhattisgarh, is situated within the boundaries of which National Park?', 'छत्तीसगढ़ का एकमात्र गेम सेंचुरी, कुटरू गेम सेंचुरी, किस राष्ट्रीय उद्यान की सीमाओं के भीतर स्थित है?', 'Kanger Valley National Park', 'कांगेर घाटी राष्ट्रीय उद्यान', 'Indravati National Park', 'इंद्रावती राष्ट्रीय उद्यान', 'Guru Ghasidas National Park', 'गुरु घासीदास राष्ट्रीय उद्यान', 'None of the above', 'उपरोक्त में से कोई नहीं', 2, 'Kutru Game Sanctuary is located within the Indravati National Park in the Bijapur district. It is the sole designated game sanctuary in the state.', 'कुटरू गेम सेंचुरी बीजापुर जिले में इंद्रावती राष्ट्रीय उद्यान के भीतर स्थित है। यह राज्य का एकमात्र नामित गेम सेंचुरी है।', 7);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Which of the following protected areas is NOT a designated Tiger Reserve in Chhattisgarh?', 'निम्नलिखित में से कौन सा संरक्षित क्षेत्र छत्तीसगढ़ में एक नामित टाइगर रिजर्व नहीं है?', 'Achanakmar', 'अचानकमार', 'Udanti-Sitanadi', 'उदंती-सीतानदी', 'Indravati', 'इंद्रावती', 'Kanger Valley', 'कांगेर घाटी', 4, 'Chhattisgarh has 4 Tiger Reserves: Indravati, Achanakmar, Udanti-Sitanadi, and the newly formed Guru Ghasidas-Tamor Pingla. Kanger Valley is a National Park but not a Tiger Reserve.', 'छत्तीसगढ़ में 4 टाइगर रिजर्व हैं: इंद्रावती, अचानकमार, उदंती-सीतानदी, और नवगठित गुरु घासीदास-तमोर पिंगला। कांगेर घाटी एक राष्ट्रीय उद्यान है लेकिन टाइगर रिजर्व नहीं है।', 8);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Match the prominent features/places with their respective National Parks:

List-I
(a) Kotumsar Cave
(b) Kutru Game Sanctuary
(c) Neelkanth Waterfall

List-II
(i) Guru Ghasidas NP
(ii) Indravati NP
(iii) Kanger Valley NP

Codes:', 'प्रमुख विशेषताओं/स्थानों को उनके संबंधित राष्ट्रीय उद्यानों के साथ सुमेलित करें:

सूची-I
(a) कुटुमसर गुफा
(b) कुटरू गेम सेंचुरी
(c) नीलकंठ जलप्रपात

सूची-II
(i) गुरु घासीदास राष्ट्रीय उद्यान
(ii) इंद्रावती राष्ट्रीय उद्यान
(iii) कांगेर घाटी राष्ट्रीय उद्यान

कूट:', '(a)-(iii), (b)-(ii), (c)-(i)', '(a)-(iii), (b)-(ii), (c)-(i)', '(a)-(ii), (b)-(iii), (c)-(i)', '(a)-(ii), (b)-(iii), (c)-(i)', '(a)-(iii), (b)-(i), (c)-(ii)', '(a)-(iii), (b)-(i), (c)-(ii)', '(a)-(i), (b)-(ii), (c)-(iii)', '(a)-(i), (b)-(ii), (c)-(iii)', 1, 'Kotumsar Cave is in Kanger Valley NP, Kutru Game Sanctuary is in Indravati NP, and Neelkanth and Chul waterfalls are in Guru Ghasidas NP.', 'कुटुमसर गुफा कांगेर घाटी राष्ट्रीय उद्यान में है, कुटरू गेम सेंचुरी इंद्रावती राष्ट्रीय उद्यान में है, और नीलकंठ तथा चूल जलप्रपात गुरु घासीदास राष्ट्रीय उद्यान में हैं।', 9);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Consider the following statements regarding the Udanti-Sitanadi Tiger Reserve:

1. It was granted the status of a combined Tiger Reserve in the year 2009.
2. Sitanadi Sanctuary is located in Dhamtari, while Udanti Sanctuary is located in Gariaband.
3. Project Tiger was initiated in these sanctuaries in 2006.

Which of the statement(s) given above is/are correct?', 'उदंती-सीतानदी टाइगर रिजर्व के संबंध में निम्नलिखित कथनों पर विचार करें:

1. इसे वर्ष 2009 में एक संयुक्त टाइगर रिजर्व का दर्जा दिया गया था।
2. सीतानदी अभयारण्य धमतरी में स्थित है, जबकि उदंती अभयारण्य गरियाबंद में स्थित है।
3. इन अभयारण्यों में प्रोजेक्ट टाइगर की शुरुआत 2006 में हुई थी।

ऊपर दिए गए कथनों में से कौन सा/से सही है/हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 4, 'All three statements are strictly correct. Sitanadi (Dhamtari) and Udanti (Gariaband) were included in Project Tiger in 2006 and officially notified as a combined Tiger Reserve in 2009.', 'तीनों कथन पूर्णतः सत्य हैं। सीतानदी (धमतरी) और उदंती (गरियाबंद) को 2006 में प्रोजेक्ट टाइगर में शामिल किया गया था और 2009 में आधिकारिक तौर पर संयुक्त टाइगर रिजर्व के रूप में अधिसूचित किया गया था।', 10);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'The state bird of Chhattisgarh, the Hill Myna (Pahari Myna), is primarily conserved in which of the following National Parks?', 'छत्तीसगढ़ के राजकीय पक्षी, पहाड़ी मैना का मुख्य रूप से किस राष्ट्रीय उद्यान में संरक्षण किया जाता है?', 'Guru Ghasidas National Park', 'गुरु घासीदास राष्ट्रीय उद्यान', 'Kanger Valley National Park', 'कांगेर घाटी राष्ट्रीय उद्यान', 'Indravati National Park', 'इंद्रावती राष्ट्रीय उद्यान', 'Sanjay National Park', 'संजय राष्ट्रीय उद्यान', 2, 'The Kanger Valley National Park in Bastar is the primary natural habitat and conservation center for the Hill Myna (Gracula religiosa peninsularis), the state bird of CG.', 'बस्तर में कांगेर घाटी राष्ट्रीय उद्यान, छ.ग. के राजकीय पक्षी पहाड़ी मैना (ग्रेकुला रिलिजिओसा पेनिनसुलरिस) का प्राथमिक प्राकृतिक आवास और संरक्षण केंद्र है।', 11);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'The blind fish species ''Kempii'' (locally known as Shankari fish), discovered by Prof. Shankar Tiwari, is found in which specific cave of Kanger Valley National Park?', 'प्रो. शंकर तिवारी द्वारा खोजी गई अंधी मछली की प्रजाति ''केम्पी'' (स्थानीय रूप से शंकरी मछली के रूप में जानी जाती है), कांगेर घाटी राष्ट्रीय उद्यान की किस विशिष्ट गुफा में पाई जाती है?', 'Dandak Cave', 'दंडक गुफा', 'Kailash Cave', 'कैलाश गुफा', 'Kotumsar Cave', 'कुटुमसर गुफा', 'Aranyak Cave', 'अरण्यक गुफा', 3, 'The unique blind fish ''Kempii'' (Shankari fish) is found in the deep pools of the Kotumsar Cave, a prominent limestone cave within the Kanger Valley National Park.', 'अद्वितीय अंधी मछली ''केम्पी'' (शंकरी मछली) कांगेर घाटी राष्ट्रीय उद्यान के भीतर एक प्रमुख चूना पत्थर गुफा, कुटुमसर गुफा के गहरे कुंडों में पाई जाती है।', 12);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Consider the following pairs of National Parks and the rivers flowing through them:

1. Indravati NP : Indravati River
2. Kanger Valley NP : Kanger River
3. Guru Ghasidas NP : Banas, Gopad, and Neyur Rivers

Which of the pairs given above are correctly matched?', 'राष्ट्रीय उद्यानों और उनसे होकर बहने वाली नदियों के निम्नलिखित युग्मों पर विचार करें:

1. इंद्रावती राष्ट्रीय उद्यान : इंद्रावती नदी
2. कांगेर घाटी राष्ट्रीय उद्यान : कांगेर नदी
3. गुरु घासीदास राष्ट्रीय उद्यान : बनास, गोपद और नेयुर नदियां

ऊपर दिए गए युग्मों में से कौन से सही सुमेलित हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 4, 'All three pairs are perfectly matched. The Banas, Gopad, and Neyur rivers are key hydrological features of the Guru Ghasidas NP in northern Chhattisgarh.', 'तीनों युग्म पूरी तरह से सुमेलित हैं। बनास, गोपद और नेयुर नदियां उत्तरी छत्तीसगढ़ में गुरु घासीदास राष्ट्रीय उद्यान की प्रमुख जलवैज्ञानिक विशेषताएं हैं।', 13);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Bhaisadarha, a natural conservation site for crocodiles, is situated on which river within the Kanger Valley National Park?', 'मगरमच्छों के लिए एक प्राकृतिक संरक्षण स्थल, भैंसादरहा, कांगेर घाटी राष्ट्रीय उद्यान के भीतर किस नदी पर स्थित है?', 'Sabari River', 'शबरी नदी', 'Indravati River', 'इंद्रावती नदी', 'Mungabahar River', 'मुनगाबहार नदी', 'Kanger River', 'कांगेर नदी', 4, 'Bhaisadarha is a deep pool (approx 4 hectares) formed on the Kanger river within the Kanger Valley National Park where crocodiles are conserved naturally.', 'भैंसादरहा कांगेर घाटी राष्ट्रीय उद्यान के भीतर कांगेर नदी पर बना ഏക गहरा कुंड (लगभग 4 हेक्टेयर) है जहां मगरमच्छों का प्राकृतिक रूप से संरक्षण किया जाता है।', 14);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Arrange the National Parks of Chhattisgarh in descending order based on their total geographical area:

1. Kanger Valley National Park
2. Guru Ghasidas National Park
3. Indravati National Park

Choose the correct sequence:', 'छत्तीसगढ़ के राष्ट्रीय उद्यानों को उनके कुल भौगोलिक क्षेत्रफल के आधार पर अवरोही (घटते) क्रम में व्यवस्थित करें:

1. कांगेर घाटी राष्ट्रीय उद्यान
2. गुरु घासीदास राष्ट्रीय उद्यान
3. इंद्रावती राष्ट्रीय उद्यान

सही क्रम चुनें:', '2, 3, 1', '2, 3, 1', '3, 2, 1', '3, 2, 1', '2, 1, 3', '2, 1, 3', '1, 3, 2', '1, 3, 2', 1, 'Descending order of area: Guru Ghasidas (1441 sq km) > Indravati (1258 sq km) > Kanger Valley (200 sq km).', 'क्षेत्रफल का अवरोही क्रम: गुरु घासीदास (1441 वर्ग किमी) > इंद्रावती (1258 वर्ग किमी) > कांगेर घाटी (200 वर्ग किमी)।', 15);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Which of the following statements is INCORRECT regarding the Indravati National Park?', 'इंद्रावती राष्ट्रीय उद्यान के संबंध में निम्नलिखित में से कौन सा कथन गलत है?', 'It was established as a National Park in 1978.', 'इसे 1978 में राष्ट्रीय उद्यान के रूप में स्थापित किया गया था।', 'It was included in Project Tiger in the year 1983.', 'इसे वर्ष 1983 में प्रोजेक्ट टाइगर में शामिल किया गया था।', 'It is the largest National Park in Chhattisgarh by area.', 'यह क्षेत्रफल के हिसाब से छत्तीसगढ़ का सबसे बड़ा राष्ट्रीय उद्यान है।', 'It forms a border with the state of Maharashtra to the west.', 'यह पश्चिम में महाराष्ट्र राज्य के साथ सीमा बनाता है।', 3, 'Statement C is incorrect because Guru Ghasidas NP (1441 sq km) is the largest in Chhattisgarh, not Indravati NP (1258 sq km). All other statements are true.', 'कथन C गलत है क्योंकि गुरु घासीदास राष्ट्रीय उद्यान (1441 वर्ग किमी) छत्तीसगढ़ में सबसे बड़ा है, न कि इंद्रावती राष्ट्रीय उद्यान (1258 वर्ग किमी)। अन्य सभी कथन सत्य हैं।', 16);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Which newly formed Tiger Reserve of Chhattisgarh shares its ecological landscape and borders with the Sanjay Dubri Tiger Reserve of Madhya Pradesh?', 'छत्तीसगढ़ का कौन सा नवगठित टाइगर रिजर्व मध्य प्रदेश के संजय दुबरी टाइगर रिजर्व के साथ अपना पारिस्थितिक परिदृश्य और सीमाएं साझा करता है?', 'Achanakmar Tiger Reserve', 'अचानकमार टाइगर रिजर्व', 'Guru Ghasidas-Tamor Pingla Tiger Reserve', 'गुरु घासीदास-तमोर पिंगला टाइगर रिजर्व', 'Indravati Tiger Reserve', 'इंद्रावती टाइगर रिजर्व', 'Udanti-Sitanadi Tiger Reserve', 'उदंती-सीतानदी टाइगर रिजर्व', 2, 'The Guru Ghasidas-Tamor Pingla Tiger Reserve in northern Chhattisgarh directly borders the Sanjay Dubri Tiger Reserve of Madhya Pradesh, forming a contiguous tiger corridor.', 'उत्तरी छत्तीसगढ़ में गुरु घासीदास-तमोर पिंगला टाइगर रिजर्व सीधे मध्य प्रदेश के संजय दुबरी टाइगर रिजर्व की सीमा से लगा है, जो एक सन्निहित बाघ गलियारा बनाता है।', 17);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Consider the following statements about the Achanakmar Tiger Reserve:

1. It was established as a Wildlife Sanctuary in 1975 in the Mungeli district.
2. It was included in Project Tiger in 2006 and declared a Tiger Reserve in 2009.
3. The Maniyari river flows through the middle of this reserve.

Which of the statement(s) given above is/are correct?', 'अचानकमार टाइगर रिजर्व के बारे में निम्नलिखित कथनों पर विचार करें:

1. इसे 1975 में मुंगेली जिले में एक वन्यजीव अभयारण्य के रूप में स्थापित किया गया था।
2. इसे 2006 में प्रोजेक्ट टाइगर में शामिल किया गया और 2009 में टाइगर रिजर्व घोषित किया गया।
3. मनियारी नदी इस रिजर्व के मध्य से होकर बहती है।

ऊपर दिए गए कथनों में से कौन सा/से सही है/हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 4, 'All statements are completely factual. Achanakmar (Mungeli, 1975) became a Project Tiger site in 2006, a TR in 2009, and the Maniyari river acts as its lifeline.', 'सभी कथन पूर्णतः तथ्यात्मक हैं। अचानकमार (मुंगेली, 1975) 2006 में प्रोजेक्ट टाइगर साइट बना, 2009 में टीआर बना, और मनियारी नदी इसकी जीवन रेखा के रूप में कार्य करती है।', 18);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Which of the following National Parks was formerly a part of Madhya Pradesh''s Sanjay National Park before the state reorganization in 2000?', 'निम्नलिखित में से कौन सा राष्ट्रीय उद्यान 2000 में राज्य पुनर्गठन से पहले मध्य प्रदेश के संजय राष्ट्रीय उद्यान का हिस्सा था?', 'Indravati National Park', 'इंद्रावती राष्ट्रीय उद्यान', 'Kanger Valley National Park', 'कांगेर घाटी राष्ट्रीय उद्यान', 'Guru Ghasidas National Park', 'गुरु घासीदास राष्ट्रीय उद्यान', 'Kanha National Park', 'कान्हा राष्ट्रीय उद्यान', 3, 'Before the formation of Chhattisgarh, Guru Ghasidas National Park was part of the undivided Sanjay National Park. Its name was changed to Guru Ghasidas in 2001.', 'छत्तीसगढ़ के गठन से पहले, गुरु घासीदास राष्ट्रीय उद्यान अविभाजित संजय राष्ट्रीय उद्यान का हिस्सा था। 2001 में इसका नाम बदलकर गुरु घासीदास कर दिया गया।', 19);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES (1294, 1158, 'Geographically, the Kanger Valley National Park extends from the Tirathgarh waterfall in the west to which river serving as the Odisha border in the east?', 'भौगोलिक दृष्टि से, कांगेर घाटी राष्ट्रीय उद्यान पश्चिम में तीरथगढ़ जलप्रपात से लेकर पूर्व में ओडिशा सीमा के रूप में कार्य करने वाली किस नदी तक फैला हुआ है?', 'Kolab River', 'कोलाब नदी', 'Sabari River', 'शबरी नदी', 'Indravati River', 'इंद्रावती नदी', 'Mahanadi River', 'महानदी नदी', 1, 'The Kanger Valley National Park officially extends from the Tirathgarh waterfall to the Kolab river, which demarcates the boundary with the state of Odisha in the east.', 'कांगेर घाटी राष्ट्रीय उद्यान आधिकारिक तौर पर तीरथगढ़ जलप्रपात से कोलाब नदी तक फैला हुआ है, जो पूर्व में ओडिशा राज्य के साथ सीमा का सीमांकन करती है।', 20);
